<template>
  <div class="page">
    <header class="head"><div><h2>申论素材</h2><p>按人民日报当天刊发稿件筛选；只保存可追溯素材，不把原创示例标成原文。入库后需人工确认。</p></div>
      <div class="actions"><el-button @click="showRules=true">筛选规则</el-button><el-button @click="exportJson">导出 JSON</el-button><el-button @click="fileInput?.click()">导入 JSON</el-button><input ref="fileInput" type="file" accept="application/json,.json" hidden @change="readFile"><el-button v-if="canWrite" type="primary" @click="edit()">新增素材</el-button></div>
    </header>
    <el-alert title="候选由人民日报联合分析生成；原文证据逐字回查，质量分达到8/10且无否决项后进入待审核，人工确认前不会作为已采用素材或发布。每日目标仅作参考，不足时不凑数。" type="info" :closable="false" />
    <div class="filters"><el-input v-model="q" clearable placeholder="搜索篇名、素材或示例" @keyup.enter="load" @clear="load"/><el-select v-model="theme" clearable placeholder="主题" @change="load"><el-option v-for="(v,k) in rules?.themes" :key="k" :label="v" :value="k"/></el-select><el-select v-model="type" clearable placeholder="类型" @change="load"><el-option v-for="(v,k) in rules?.types" :key="k" :label="v" :value="k"/></el-select><el-select v-model="status" clearable placeholder="审核状态" @change="load"><el-option label="待审核" value="pending"/><el-option label="已确认" value="confirmed"/><el-option label="已退回" value="rejected"/></el-select><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="来源开始" end-placeholder="来源结束" @change="load"/><el-button @click="load">筛选</el-button></div>
    <div class="stats"><el-tag>待审核 {{ stats.pending || 0 }}</el-tag><el-tag type="success">已确认 {{ stats.confirmed || 0 }}</el-tag><el-tag type="danger">已退回 {{ stats.rejected || 0 }}</el-tag></div>
    <el-table v-loading="loading" :data="items" stripe>
      <el-table-column label="素材 / 来源" min-width="320"><template #default="{row}"><b>{{ row.text }}</b><div class="muted">{{ row.source_title }} · {{ row.source_date }} · {{ row.source_section || '版面未填' }}</div></template></el-table-column>
      <el-table-column label="类别 / 主题" width="150"><template #default="{row}">{{ rules?.types?.[row.type] || row.type }}<div class="muted">{{ rules?.themes?.[row.theme_code] }}</div></template></el-table-column>
      <el-table-column label="场景 / 评分" width="145"><template #default="{row}">{{ rules?.scenes?.[row.scene_code] }}<div class="muted">{{ row.quality_score == null ? '待评分' : `${row.quality_score}/10 分` }}</div></template></el-table-column>
      <el-table-column label="审核" width="100"><template #default="{row}"><el-tag :type="row.review_status==='confirmed'?'success':row.review_status==='rejected'?'danger':'warning'">{{ statusName(row.review_status) }}</el-tag></template></el-table-column>
      <el-table-column label="操作" width="170"><template #default="{row}"><el-button link @click="edit(row)">查看 / 编辑</el-button><el-button v-if="canWrite && row.review_status!=='confirmed' && row.quality_score>=8 && !row.veto" link type="success" @click="confirmRow(row)">确认</el-button><el-button v-if="canWrite" link type="danger" @click="del(row)">删除</el-button></template></el-table-column>
    </el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/>
    <el-drawer v-model="editing" :title="draft?.id ? '申论素材详情' : '新增申论素材'" size="620px"><el-form v-if="draft" label-position="top">
      <el-form-item label="素材正文 / 事实摘要"><el-input v-model="draft.text" type="textarea" :rows="3"/></el-form-item>
      <el-row :gutter="12"><el-col :span="12"><el-form-item label="物料类型"><el-select v-model="draft.type" style="width:100%"><el-option v-for="(v,k) in rules?.types" :key="k" :label="v" :value="k"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="主主题"><el-select v-model="draft.theme_code" style="width:100%"><el-option v-for="(v,k) in rules?.themes" :key="k" :label="v" :value="k"/></el-select></el-form-item></el-col></el-row>
      <el-form-item label="主题要素（逗号分隔）"><el-input v-model="elementsText" placeholder="做法、成效"/></el-form-item><el-form-item label="主使用场景"><el-select v-model="draft.scene_code" style="width:100%"><el-option v-for="(v,k) in rules?.scenes" :key="k" :label="v" :value="k"/></el-select></el-form-item>
      <el-row :gutter="12"><el-col :span="12"><el-form-item label="来源日期"><el-date-picker v-model="draft.source_date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="来源版面"><el-input v-model="draft.source_section"/></el-form-item></el-col></el-row><el-form-item label="来源文章标题"><el-input v-model="draft.source_title"/></el-form-item><el-form-item label="原文链接"><el-input v-model="draft.source_url"/></el-form-item>
      <el-form-item label="原文核对摘录（必须能在来源正文逐字找到）"><el-input v-model="draft.source_evidence" type="textarea" :rows="4" maxlength="800"/></el-form-item>
      <el-form-item v-if="draft.type==='template'" label="模板提炼锚点（逐字原句）"><el-input v-model="draft.source_anchor" type="textarea" :rows="2"/></el-form-item>
      <template v-if="draft.type==='quote'"><el-form-item label="语录说话人"><el-input v-model="draft.speaker"/></el-form-item><el-form-item label="包含归属信息的原文上下文"><el-input v-model="draft.context_15" type="textarea" :rows="3"/></el-form-item></template>
      <template v-if="draft.type==='case'"><el-form-item label="事实（谁、在哪、做什么）"><el-input v-model="draft.fact" type="textarea" :rows="2"/></el-form-item><el-form-item label="结果"><el-input v-model="draft.result" type="textarea" :rows="2"/></el-form-item><el-form-item label="能证明什么"><el-input v-model="draft.proves"/></el-form-item><el-form-item label="使用边界 / 不能证明什么"><el-input v-model="draft.do_not_use_for"/></el-form-item></template>
      <el-form-item label="质量评分（按维度填写；总分自动汇总）"><div class="score-grid"><label v-for="(max,name) in rules?.quality_gate?.dimensions" :key="name">{{ name }} <el-input-number v-model="scoreParts[name]" :min="0" :max="max" size="small"/></label></div><div class="muted">当前合计 {{ scoreTotal ?? '未评分' }}{{ scoreTotal == null ? '' : '/10 分' }}；达到8分且无否决项方可确认。</div></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="否决项"><el-switch v-model="draft.veto"/></el-form-item></el-col><el-col :span="12"><el-form-item label="审核状态"><el-select v-model="draft.review_status"><el-option label="待审核" value="pending"/><el-option label="已确认" value="confirmed"/><el-option label="已退回" value="rejected"/></el-select></el-form-item></el-col></el-row><el-button v-if="canWrite" type="primary" :loading="saving" @click="save">保存</el-button>
    </el-form></el-drawer>
    <el-drawer v-model="showRules" title="申论素材筛选规则" size="560px"><div v-if="rules" class="rules"><p><b>规则版本：</b>{{ rules.version }} · <b>来源：</b>{{ rules.source }}</p><p><b>来源排除：</b>{{ rules.exclude?.join('、') }}</p><p><b>质量门：</b>{{ rules.quality_gate.pass_score }}/{{ rules.quality_gate.max_score }} 分；独立成义、主题咬合、场景匹配、可改写、规范、可追溯、不重复。</p><p><b>一票否决：</b>{{ rules.quality_gate.veto?.join('、') }}</p><p><b>主题闭集：</b>{{ Object.values(rules.themes).join('、') }}</p><p><b>案例规范：</b>正文压缩至60–90字；事实、结果、证明点、使用边界齐备；主场景固定为例证。</p><p><b>语录必填：</b>可核对原文、说话人及原文上下文；无法核对不得入库。</p><p><b>示例规范：</b>原创改写控制在80–120字，必须标注为示例，不得冒充人民日报原句或补充来源未提供的事实。</p><el-table :data="quotaRows" size="small"><el-table-column prop="name" label="类型"/><el-table-column prop="target" label="目标"/><el-table-column prop="min" label="最低"/></el-table></div></el-drawer>
    <el-dialog v-model="importVisible" title="导入预览" width="760px"><p>校验 {{ importResults.length }} 条；无效记录会阻止整批导入，重复记录将跳过。</p><el-table :data="importResults" max-height="420"><el-table-column prop="index" label="#" width="55"/><el-table-column prop="title" label="来源文章"/><el-table-column prop="status" label="结果" width="100"/><el-table-column prop="error" label="问题"/></el-table><template #footer><el-button @click="importVisible=false">取消</el-button><el-button type="primary" :disabled="importResults.some(x=>x.status==='invalid')" @click="doImport">导入有效记录</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import * as api from '@/api/shenlunMaterials'
const auth=useAuthStore(), canWrite=computed(()=>auth.hasPermission('rmrb:write'))
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date())
const rules=ref<Record<string,any>>(), items=ref<api.ShenlunMaterial[]>([]), stats=ref<Record<string,number>>({}), total=ref(0), page=ref(1), loading=ref(false), q=ref(''), theme=ref(''), type=ref(''), status=ref(''), dateRange=ref<string[]|null>(null)
const editing=ref(false),showRules=ref(false),saving=ref(false),draft=ref<api.ShenlunMaterial>(),elementsText=ref(''),fileInput=ref<HTMLInputElement>(),importVisible=ref(false),importItems=ref<unknown[]>([]),importDate=ref(''),importResults=ref<{index:number;status:string;error?:string;title?:string;score?:number}[]>([])
const scoreParts=ref<Record<string,number>>({})
const scoreKeys=['独立成义','主题咬合','场景匹配','可改写','规范','可追溯','不重复']
const scoreTotal=computed(()=>scoreKeys.every(key=>Number.isFinite(scoreParts.value[key]))?scoreKeys.reduce((sum,key)=>sum+Number(scoreParts.value[key]),0):null)
const quotaRows=computed(()=>Object.entries(rules.value?.daily_quota||{}).map(([key,v]:[string,any])=>({name:rules.value?.types?.[key]||key,target:v.target,min:v.min})))
function statusName(s:string){return s==='confirmed'?'已确认':s==='rejected'?'已退回':'待审核'}
async function load(){loading.value=true;try{const d=await api.list({q:q.value,theme:theme.value,item_type:type.value,status:status.value,start:dateRange.value?.[0],end:dateRange.value?.[1],page:page.value});items.value=d.items;total.value=d.total;stats.value=d.stats}catch(e){ElMessage.error(e instanceof Error?e.message:'加载失败')}finally{loading.value=false}}
function empty():api.ShenlunMaterial{return {type:'case',text:'',theme_code:'ms',theme_element:[],scene_code:'essay_example',usage_note:'',example_topic:'',example_body:'',source_date:today,collected_date:today,source_title:'',source_section:'',source_url:'',quality_score:null,veto:false,review_status:'pending'}}
function edit(row?:api.ShenlunMaterial){const current=row?JSON.parse(JSON.stringify(row)) as api.ShenlunMaterial:empty();draft.value=current;elementsText.value=(Array.isArray(current.theme_element)?current.theme_element:[current.theme_element]).filter(Boolean).join('、');scoreParts.value={...((current.quality_breakdown as Record<string,number>)||{})};editing.value=true}
async function save(){const current=draft.value;if(!current)return;current.theme_element=elementsText.value.split(/[、,，]/).map(s=>s.trim()).filter(Boolean);if(scoreTotal.value==null){delete current.quality_breakdown;current.quality_score=null}else{current.quality_breakdown=scoreParts.value;current.quality_score=scoreTotal.value}saving.value=true;try{await api.save(current);ElMessage.success('已保存');editing.value=false;load()}catch(e){ElMessage.error(e instanceof Error?e.message:'保存失败')}finally{saving.value=false}}
async function confirmRow(row:api.ShenlunMaterial){try{await api.save({...row,review_status:'confirmed'});ElMessage.success('已确认');load()}catch(e){ElMessage.error(e instanceof Error?e.message:'审核失败')}}
async function del(row:api.ShenlunMaterial){try{await ElMessageBox.confirm('确定删除这条素材？','删除确认');await api.remove(row.id!);ElMessage.success('已删除');load()}catch{}}
async function exportJson(){try{const data=await api.exportItems();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({collected_date:today,items:data},null,2)],{type:'application/json'}));a.download='人民日报申论素材.json';a.click();URL.revokeObjectURL(a.href)}catch(e){ElMessage.error(e instanceof Error?e.message:'导出失败')}}
async function readFile(event:Event){const f=(event.target as HTMLInputElement).files?.[0];(event.target as HTMLInputElement).value='';if(!f)return;try{const json=JSON.parse(await f.text());const records=Array.isArray(json)?json:json.items;importDate.value=json.collected_date||today;if(!Array.isArray(records))throw new Error('JSON 顶层需要是数组或包含 items 数组');importItems.value=records;importResults.value=await api.previewImport(records,importDate.value);importVisible.value=true}catch(e){ElMessage.error(e instanceof Error?e.message:'JSON 文件无法解析')}}
async function doImport(){try{const d=await api.importItems(importItems.value,importDate.value);ElMessage.success(`导入 ${d.added} 条，跳过重复 ${d.skipped} 条`);importVisible.value=false;load()}catch(e){ElMessage.error(e instanceof Error?e.message:'导入失败')}}
onMounted(async()=>{try{rules.value=await api.getRules()}catch{}load()})
</script>
<style scoped>
.page{padding:20px}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px}.head h2{margin:0 0 6px}.head p,.muted{color:var(--el-text-color-secondary);font-size:13px}.actions{display:flex;gap:8px}.filters{display:flex;gap:10px;align-items:center;margin:16px 0;flex-wrap:wrap}.filters>.el-input{width:240px}.filters>.el-select{width:150px}.stats{display:flex;gap:8px;margin:12px 0}.muted{margin-top:5px}.el-pagination{justify-content:flex-end;margin-top:16px}.rules p{line-height:1.8}.rules b{color:var(--el-text-color-primary)}.score-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%}.score-grid label{display:flex;align-items:center;justify-content:space-between;gap:10px}
</style>
